/**
 * Renders the Uniwind theme layer from the tokens — a pure function shared by
 * `scripts/theme-css.mjs` (which writes the file) and `tokens.test.mjs`.
 */
import { brand, fonts, radius, themes } from './tokens.ts'

const kebab = (key) => key.replace(/([a-z])([A-Z0-9])/g, '$1-$2').toLowerCase()
const lines = (prefix, record, indent) =>
  Object.entries(record)
    .map(([key, value]) => `${indent}--${prefix}-${kebab(key)}: ${typeof value === 'number' ? `${value}px` : value};`)
    .join('\n')

export function renderThemeCss() {
  return [
    '/* GENERATED by scripts/theme-css.mjs from src/theme/tokens.ts — edit the tokens, not this file. */',
    '@theme {',
    lines('color', brand, '  '),
    lines('radius', radius, '  '),
    lines('font', fonts, '  '),
    '}',
    '',
    '@layer theme {',
    '  :root {',
    '    @variant dark {',
    lines('color', themes.dark, '      '),
    '    }',
    '    @variant light {',
    lines('color', themes.light, '      '),
    '    }',
    '  }',
    '}',
    '',
  ].join('\n')
}
